CREATE TABLE IF NOT EXISTS project_tracker (
  id INTEGER PRIMARY KEY,
  customer TEXT,
  project TEXT,
  region TEXT,
  province TEXT,
  site_id TEXT,
  new_xl_id TEXT,
  sow TEXT,
  scope TEXT,
  po_status TEXT,
  ti_status TEXT,
  payment_status TEXT,
  wcc_status TEXT,
  attention_reason TEXT,
  attention_level TEXT,
  action_required TEXT,
  action_owner TEXT,
  last_update TEXT,
  action_due_date TEXT,
  action_status TEXT,
  days_to_due INTEGER,
  follow_up_flag TEXT,
  report_flag TEXT
);
DELETE FROM project_tracker;
